        private void CheckForUnionMemberErrors(BindingDiagnosticBag diagnostics)
        {
            if (declaration.Kind != DeclarationKind.Union)
            {
                return;
            }

            foreach (var member in GetMembersAndInitializers().NonTypeMembers)
            {
                switch (member)
                {
                    case SourceMemberFieldSymbol field when !field.IsStatic && field.AssociatedSymbol is null:
                        // Instance field. Backing fields of auto-properties and field-like events are
                        // synthesized (or reported via their associated member) and are skipped here.
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, field.GetFirstLocation());
                        break;

                    case SourcePropertySymbolBase { IsStatic: false, IsAutoPropertyOrUsesFieldKeyword: true } property:
                        // Auto-property (including explicit interface implementations) or a property that uses the 'field' keyword.
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, property.GetFirstLocation());
                        break;

                    case EventSymbol { IsStatic: false, HasAssociatedField: true } @event:
                        // Field-like event.
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, @event.GetFirstLocation());
                        break;

                    case SourceConstructorSymbol { MethodKind: MethodKind.Constructor } constructor:
                        CheckUnionConstructor(constructor, diagnostics);
                        break;
                }
            }
        }

        private static void CheckUnionConstructor(SourceConstructorSymbol constructor, BindingDiagnosticBag diagnostics)
        {
            var syntax = constructor.GetSyntax();

            if (constructor.ParameterCount == 1)
            {
                diagnostics.Add(ErrorCode.ERR_InstanceCtorWithOneParameterInUnion, syntax.Identifier.GetLocation());
            }

            var initializer = syntax.Initializer;
            if (initializer is null || initializer.Kind() != SyntaxKind.ThisConstructorInitializer)
            {
                // No 'this' initializer at all.
                diagnostics.Add(ErrorCode.ERR_UnionConstructorCallsDefaultConstructor, syntax.Identifier.GetLocation());
            }
            else if (initializer.ArgumentList.Arguments.Count == 0)
            {
                // A 'this()' initializer that calls the default parameterless constructor.
